create extension if not exists vector;
create extension if not exists pgcrypto;
create type processing_state as enum ('queued','running','complete','failed','retrying','dead');
create table profiles(id uuid primary key references auth.users on delete cascade, display_name text not null default 'Kaden Condie', context jsonb not null default '{}', created_at timestamptz not null default now());
create table goals(id uuid primary key default gen_random_uuid(), owner_id uuid references profiles not null, name text not null, description text, type text not null, priority smallint default 3 check(priority between 1 and 5), time_horizon text,status text default 'active',success_definition text,constraints text,created_at timestamptz default now());
create table projects(id uuid primary key default gen_random_uuid(),owner_id uuid references profiles not null,name text not null,description text,objective text,status text default 'active',priority smallint default 3,deadline date,metadata jsonb default '{}',created_at timestamptz default now());
create table skills(id uuid primary key default gen_random_uuid(),owner_id uuid references profiles not null,name text not null,level text,metadata jsonb default '{}',unique(owner_id,name));
create table sources(id uuid primary key default gen_random_uuid(),platform text not null,label text,external_id text,metadata jsonb default '{}',created_at timestamptz default now());
create table raw_events(id uuid primary key default gen_random_uuid(),provider text not null,external_id text,payload jsonb not null,signature_valid boolean not null,status text not null,error text,received_at timestamptz default now(),unique(provider,external_id));
create table captures(id uuid primary key default gen_random_uuid(),owner_id uuid references profiles,capture_type text not null,source_id uuid references sources,source_platform text,source_identifier text,canonical_url text,raw_url text,original_text text,user_note text,raw_metadata jsonb default '{}',raw_event_id uuid references raw_events,processing_status processing_state default 'queued',analysis_status text default 'pending',content_availability text default 'UNAVAILABLE',error text,duplicate_of_id uuid references captures,repeat_count int default 1,captured_at timestamptz default now(),created_at timestamptz default now());
create unique index captures_source_identifier_uq on captures(source_platform,source_identifier) where source_identifier is not null;
create table knowledge_items(id uuid primary key default gen_random_uuid(),capture_id uuid references captures on delete cascade not null,title text not null,summary text,core_idea text,why_saved text,content_type text,importance real,novelty real,confidence real,status text default 'new',evidence jsonb default '{}',embedding vector(1536),last_viewed timestamptz,last_actioned timestamptz,last_researched timestamptz,last_relevant_event timestamptz,staleness_score real default 0,created_at timestamptz default now(),updated_at timestamptz default now());
create table knowledge_chunks(id uuid primary key default gen_random_uuid(),item_id uuid references knowledge_items on delete cascade not null,content text not null,chunk_index int not null,embedding vector(1536),metadata jsonb default '{}');
create table entities(id uuid primary key default gen_random_uuid(),owner_id uuid references profiles,name text not null,canonical_name text not null,entity_type text not null,aliases text[] default '{}',metadata jsonb default '{}',unique(owner_id,canonical_name,entity_type));
create table item_entities(item_id uuid references knowledge_items on delete cascade,entity_id uuid references entities on delete cascade,confidence real,source text,primary key(item_id,entity_id));
create table relationships(id uuid primary key default gen_random_uuid(),owner_id uuid references profiles,subject_type text not null,subject_id uuid not null,predicate text not null,object_type text not null,object_id uuid not null,confidence real not null check(confidence between 0 and 1),source text not null,metadata jsonb default '{}',created_at timestamptz default now());
create table opportunities(id uuid primary key default gen_random_uuid(),owner_id uuid references profiles not null,title text not null,thesis text,status text default 'research',target_customers text[],problem text,offer text,revenue_model text,evidence jsonb default '{}',counter_evidence jsonb default '{}',risks jsonb default '{}',fastest_experiment text,initial_score numeric(3,1),verified_score numeric(3,1),interest_signal real default 0,evidence_strength real default 0,created_at timestamptz default now(),updated_at timestamptz default now());
create table opportunity_scores(id uuid primary key default gen_random_uuid(),opportunity_id uuid references opportunities on delete cascade,dimensions jsonb not null,weighted_score numeric(3,1) not null,reasoning jsonb not null,score_type text default 'initial',created_at timestamptz default now());
create table actions(id uuid primary key default gen_random_uuid(),owner_id uuid references profiles not null,title text not null,description text,status text default 'inbox',priority smallint default 3,project_id uuid references projects,opportunity_id uuid references opportunities,source_item_id uuid references knowledge_items,due_date timestamptz,estimated_minutes int,actual_minutes int,expected_value text,created_by text default 'owner',created_at timestamptz default now());
create table experiments(id uuid primary key default gen_random_uuid(),owner_id uuid references profiles not null,opportunity_id uuid references opportunities,hypothesis text not null,test text not null,success_criteria text,maximum_minutes int,maximum_cost numeric,required_assets jsonb default '[]',result text,conclusion text,status text default 'planned',created_at timestamptz default now());
create table research_runs(id uuid primary key default gen_random_uuid(),opportunity_id uuid references opportunities,status processing_state default 'queued',questions jsonb,conclusion text,score_before numeric(3,1),score_after numeric(3,1),created_at timestamptz default now(),completed_at timestamptz);
create table research_sources(id uuid primary key default gen_random_uuid(),research_run_id uuid references research_runs on delete cascade,url text not null,title text,publisher text,claim text,source_type text,accessed_at timestamptz default now());
create table agent_runs(id uuid primary key default gen_random_uuid(),owner_id uuid references profiles,agent text not null,model text,prompt_version text not null,input_references jsonb default '[]',structured_output jsonb,status processing_state default 'running',started_at timestamptz default now(),completed_at timestamptz,input_tokens int,output_tokens int,estimated_cost numeric,error text);
create table integration_events(id uuid primary key default gen_random_uuid(),raw_event_id uuid references raw_events,provider text,event_type text,status text,metadata jsonb default '{}',created_at timestamptz default now());
create table external_connections(id uuid primary key default gen_random_uuid(),owner_id uuid references profiles,label text not null,server_url text,enabled boolean default false,allowed_tools text[] default '{}',approval_policy text default 'always',status text default 'not_connected',metadata jsonb default '{}',created_at timestamptz default now());
create table jobs(id uuid primary key default gen_random_uuid(),job_type text not null,payload jsonb not null,status processing_state default 'queued',attempt_count int default 0,last_error text,next_retry_at timestamptz,locked_at timestamptz,locked_by text,created_at timestamptz default now(),completed_at timestamptz);
create table daily_briefs(id uuid primary key default gen_random_uuid(),owner_id uuid references profiles,brief_date date not null,content jsonb not null,created_at timestamptz default now(),unique(owner_id,brief_date));
create table weekly_briefs(id uuid primary key default gen_random_uuid(),owner_id uuid references profiles,week_start date not null,content jsonb not null,created_at timestamptz default now(),unique(owner_id,week_start));
create table audit_logs(id uuid primary key default gen_random_uuid(),owner_id uuid references profiles,actor text,action text not null,target_type text,target_id uuid,input_summary text,result text,created_at timestamptz default now());
create or replace function match_knowledge(query_embedding vector(1536), match_threshold float, match_count int) returns table(id uuid,title text,summary text,similarity float) language sql stable as $$ select k.id,k.title,k.summary,1-(k.embedding <=> query_embedding) similarity from knowledge_items k where 1-(k.embedding <=> query_embedding)>match_threshold order by k.embedding <=> query_embedding limit match_count $$;
alter table profiles enable row level security;alter table goals enable row level security;alter table projects enable row level security;alter table skills enable row level security;alter table captures enable row level security;alter table knowledge_items enable row level security;alter table opportunities enable row level security;alter table actions enable row level security;alter table experiments enable row level security;
create policy owner_profiles on profiles for all using(id=auth.uid()) with check(id=auth.uid());
create policy owner_goals on goals for all using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy owner_projects on projects for all using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy owner_skills on skills for all using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy owner_captures on captures for all using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy owner_opportunities on opportunities for all using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy owner_actions on actions for all using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy owner_experiments on experiments for all using(owner_id=auth.uid()) with check(owner_id=auth.uid());
